/**
 * API client for the Wahlkompass.
 * Uses BTW 2025 data with real party positions extracted from Wahlprogramme.
 */

import type { ElectionData, Election, Position as PositionType } from "./types";

const API_URL = process.env.NEXT_PUBLIC_API_URL ?? "";

async function fetchJson<T>(path: string): Promise<T> {
  const res = await fetch(`${API_URL}${path}`, {
    headers: { Accept: "application/json" },
    cache: "no-store",
  });
  if (!res.ok) throw new Error(`API ${res.status}: ${path}`);
  return (await res.json()) as T;
}

export async function getElections(): Promise<Election[]> {
  if (API_URL) {
    try { return await fetchJson<Election[]>("/api/elections"); } catch {}
  }
  return [mockElection];
}

export async function getElectionData(electionId: string): Promise<ElectionData> {
  if (API_URL) {
    try { return await fetchJson<ElectionData>(`/api/elections/${electionId}`); } catch {}
  }
  return mockDataset(electionId);
}

export async function getMethodik(): Promise<string> {
  if (API_URL) {
    try { return await fetchJson<string>("/api/methodik"); } catch {}
  }
  return MOCK_METHODIK;
}

